    Verified:
    - demo1: 10x4 grid, input=output (no corners-all-same condition)
    - demo2: 30x25->29x25 grid, corners all 6, transform 6->3 between 7s
    """
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

