    # Column spans
    for c in range(w):
        sps = sorted([r for r in range(h) if grid[r][c] == 7])
        for i in range(len(sps) - 1):
            for r in range(sps[i] + 1, sps[i+1]):
                if result[r][c] == 6:
                    result[r][c] = 3

